// Package text measures and lays out label text.
package text

import (
	"strconv"
	"sync"
)

// Style bits of a span of text.
const (
	Bold   = 1
	Italic = 2
	Mono   = 4
)

// Measurer gives the width in pixels of text in a font size and style.
type Measurer interface {
	Width(text string, size float64, style int) float64
}

// Advance widths of printable ASCII in thousandths of an em, two base-36 digits each.
// Generated by scripts/gen-metrics.mjs from Arial.
const (
	regularPacked = "7q7q9vfgfgopij5b9999atg87q997q7qfgfgfgfgfgfgfgfgfgfg7q7qg8g8g8fgs7ijijk2k2ijgzlmk27qdwijfgn5k2lmijlmk2ijgzk2ijq8ijijgz7q7q7qd1fg99fgfgdwfgfg7qfgfg6666dw66n5fgfgfgfg99dw7qfgdwk2dwdwdw9a789ag8"
	boldPacked    = "7q99d6fgfgopk26m9999atg87q997q7qfgfgfgfgfgfgfgfgfgfg9999g8g8g8gzr3k2k2k2k2ijgzlmk27qfgk2gzn5k2lmijlmk2ijgzk2ijq8ijijgz997q99g8fg99fggzfggzfg99gzgz7q7qfg7qopgzgzgzgzatfg99gzfglmfgfgdwat7satg8"
)

func unpack(packed string) [95]int {
	var out [95]int
	for i := 0; i < 95; i++ {
		n, _ := strconv.ParseInt(packed[i*2:i*2+2], 36, 32)
		out[i] = int(n)
	}
	return out
}

var (
	tablesOnce    sync.Once
	regular, bold [95]int
)

func isWide(c rune) bool {
	return (c >= 0x1100 && c <= 0x115f) ||
		(c >= 0x2e80 && c <= 0xa4cf) ||
		(c >= 0xac00 && c <= 0xd7a3) ||
		(c >= 0xf900 && c <= 0xfaff) ||
		(c >= 0xfe30 && c <= 0xfe4f) ||
		(c >= 0xff00 && c <= 0xff60) ||
		(c >= 0xffe0 && c <= 0xffe6) ||
		(c >= 0xd800 && c <= 0xdbff)
}

func isZeroWidth(c rune) bool {
	return (c >= 0x300 && c <= 0x36f) ||
		(c >= 0x200b && c <= 0x200f) ||
		(c >= 0xdc00 && c <= 0xdfff) ||
		(c >= 0xfe00 && c <= 0xfe0f) ||
		c == 0xfeff
}

type metrics struct{}

// Metrics estimates widths from a table of Arial advances. It is the measurer the TypeScript
// library uses where no canvas is available, and the default here.
var Metrics Measurer = metrics{}

func (metrics) Width(text string, size float64, style int) float64 {
	tablesOnce.Do(func() {
		regular = unpack(regularPacked)
		bold = unpack(boldPacked)
	})
	mono := style&Mono != 0
	table := &regular
	if style&Bold != 0 {
		table = &bold
	}
	units := 0
	for _, c := range text {
		// A character outside the BMP is a surrogate pair in JavaScript: a wide high half and a
		// zero-width low half.
		if c >= 0x10000 {
			c = 0xd800
		}
		switch {
		case c < 32:
		case c < 127:
			if mono {
				units += 600
			} else {
				units += table[c-32]
			}
		case isZeroWidth(c):
		case isWide(c):
			if mono {
				units += 1200
			} else {
				units += 1000
			}
		default:
			if mono {
				units += 600
			} else {
				units += 580
			}
		}
	}
	return float64(units) * size / 1000
}
